#!/usr/bin/env python3
"""Prepare staged native fixtures for each integrated lot48 occurrence.
These are dialogue-window fixtures, not natural menu/battle availability proofs.
"""
import argparse,hashlib,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--rom',type=Path,required=True);p.add_argument('--diagnostic-core',type=Path,required=True);a=p.parse_args();root=Path(__file__).resolve().parents[2];rom=a.rom.read_bytes();build=json.loads((root/'verification/build_report_lot48_checkpoint.json').read_text());assert hashlib.sha256(rom).hexdigest()==build['output_sha256'];rows=json.loads((root/'traduction/traduction_v54.json').read_text());new=[r for r in rows if r['lot']=='48'];assert len(new)==build['new_bounded_occurrences'];aliases=json.loads((root/'verification/aliases_lot48.json').read_text());canonical=[r for r in new if r['id'] not in aliases and r['english']!=r['french']];assert len(canonical)==400
suite={'lot':48,'rom_sha256':build['output_sha256'],'case_count':len(new),'groups':[],'scope':'Native dialogue-window fixtures only. Native help copier width proofs and actual menu navigation are separate. No actual battle progression, event availability, timing or debug classification proof.'}
for name,blocks in [('help',[8,9,10,11]),('labels',[16]),('actions',[19])]:
 cases=[[r['block_id'],r['string_id'],f"b{r['block_id']:03}s{r['string_id']:03}"] for r in new if r['block_id'] in blocks];filename=f'cases_lot48_400_{name}.json';(root/'verification/reproduction'/filename).write_text(json.dumps(cases,indent=2)+'\n');suite['groups'].append({'name':name,'cases':filename,'core_filename':a.diagnostic_core.name,'core_sha256':hashlib.sha256(a.diagnostic_core.read_bytes()).hexdigest()})
(root/'verification/reproduction/suite_lot48_400.json').write_text(json.dumps(suite,indent=2)+'\n');(root/'verification/reproduction/cases_v54.json').write_text(json.dumps([[r['block_id'],r['string_id'],r['id']] for r in new],indent=2)+'\n');(root/'verification/lot48_counting.json').write_text(json.dumps({'lot':48,'new_distinct_sources':400,'new_occurrences':len(new),'canonical_sources':[{'id':r['id'],'english':r['english'],'french':r['french']} for r in canonical],'aliases_excluded':aliases,'status':'Runtime and actual-use validation pending; not a released lot'},ensure_ascii=False,indent=2)+'\n');print('Prepared',len(new),'staged fixtures;400 canonical candidate bodies, actual-use validation pending.')
